import { asRecord, extractApiData, extractCollection, pickString, pickNumber, formatCurrency, formatDateTime } from "@/lib/proxy-client";
import type { LiveStats } from "@/hooks/use-comments";

import {
  LoadingState,
  ErrorState,
  EmptyState,
  formatNumber,
