    muted: "bg-[var(--surface-muted)] text-[var(--muted)]",
    danger: "bg-[rgba(255,69,58,0.14)] text-[rgb(255,69,58)]",
  }[tone];

  return (
    <span className={`inline-flex rounded-full px-3 py-1 text-[11px] font-semibold uppercase tracking-[0.18em] ${tones}`}>
      {children}
    </span>
  );
}

